static string recvline(int fd) {
	string line;
	int ret;

	// Reserve arbitrary amount of space to avoid small memory reallocations.
	line.reserve(128);

	do {
		char c;
		ret = recv(fd, &c, 1, 0);
		if (ret == 1) {
			if (c == '\n')
				return line;
			line += c;
		}
	} while (ret == 1 || (ret == -1 && errno == EINTR));

	return line;
}

